"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0961-10-15:0":{"b": ["Abd ar-Rahman III morì a Cordova (2 Ramadan 350); il califfato passò ad al-Hakam II.", "16c7e725"], "d": ["Abd ar-Rahman III morì a Cordova (2 Ramadan 350); il califfato passò ad al-Hakam II.", "16c7e725"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0972-01-01:0":{"b": ["Il califfo fatimide al-Muizz nominò Buluggin governatore del Maghreb e lo stabilì a Qayrawan; iniziò il periodo degli Ziridi", "562089c8"], "d": ["Il califfo fatimide al-Muizz li-Din Allah, nominato Buluggin b. Ziri governatore del Maghreb, lo stabilì a Qayrawan (361/972) e, trasferito il centro amministrativo dello Stato in Egitto, lasciò la regione.", "26bbc5b2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0976-10-02:0":{"b": ["Dopo la morte di al-Hakam II, Hisham II, di undici-dodici anni, divenne califfo.", "359fba92"], "d": ["Dopo la morte di al-Hakam II, Hisham II, di undici-dodici anni, divenne califfo.", "359fba92"]},
